/* CQA Studio: plain HTML/CSS/JavaScript, suitable for an embedded web resource. */
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 9h9M7 13h6"/>',check:'<path d="m8 12 3 3 6-7"/><rect x="4" y="3" width="16" height="19" rx="3"/>',appeal:'<path d="M12 8v5M12 17h.01"/><path d="M10 3 2 18a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 3a2 2 0 0 0-4 0Z"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 2-1 3-3 1-3-1-2 4 2 2v3l-2 2 2 4 3-1 3 1 1 3h4l1-3 3-1 3 1 2-4-2-2v-3l2-2-2-4-3 1-3-1-1-3Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',play:'<path d="m9 4 12 8-12 8Z"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',left:'<path d="M20 12H4m5-5-5 5 5 5"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',phone:'<path d="M5 3h4l2 5-3 2c2 4 3 5 6 7l2-3 5 2v4c0 2-2 2-4 2C8 20 3 14 2 6c0-2 1-3 3-3Z"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',chart:'<path d="M4 4v16h17M9 15v-4m5 4V7m5 8v-6"/>',link:'<path d="M14 3h7v7m0-7L10 14M10 3H4v17h17v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',refresh:'<path d="M20 8a9 9 0 1 0 1 7M20 3v5h-5"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',save:'<path d="M4 3h14l3 3v15H3V3Zm3 0v7h10V3M7 21v-7h10v7"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.chat}</svg>`;
let data,
    activeChecklist='',
    engine='model',
    modelKey='',
    draft=null,
    draftId='',
    evaluationId='',
    filters={channel:'all',language:'all',status:'all',search:'',page:1},
    batch=null,
    busy=false;
let toastTimer;
const date=iso=>new Date(iso).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Almaty'});
const answerText=a=>a===null?'N/A':a==='pending'?'Проверить':a===true?'Да':a===false?'Нет':String(a);
const latest=id=>data.evaluations.filter(e=>e.conversationId===id).at(-1);
const openAppeals=()=>data.appeals.filter(a=>a.status==='open');
const currentCheck=()=>data.checklists.find(c=>c.id===activeChecklist)||data.checklists[0];
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}

async function api(path,body){
    const response=await fetch('/api/'+path,
        {method:body?'POST':'GET',
            headers:body?{'Content-Type':'application/json',
                ...(modelKey?{'X-CQA-Model-Key':modelKey}:{})}:{},
            body:body?JSON.stringify(body):undefined});let result;try{result=await response.json();
            }catch{
                throw new Error('Сервер вернул некорректный ответ.');}
    if(!response.ok){
        const error=new Error(result.error||`Ошибка ${response.status}`);
        error.code=result.code||'';
        error.status=response.status;
        error.retryAfterSeconds=result.retryAfterSeconds||null;throw error;}
    return result;
}
async function reload(){data=await api('state');if(!data.checklists.some(c=>c.id===activeChecklist))activeChecklist=data.defaultChecklistId||data.checklists[0].id;}
function route(){const [view='overview',id='']=location.hash.replace(/^#\/?/,'').split('/');return {view:view||'overview',id:decodeURIComponent(id)};}
function nav(view,label,name,count=''){return `<a href="#${view}" class="${route().view===view?'active':''}">${icon(name)}<span>${label}</span>${count!==''?`<span class="nav-count">${esc(count)}</span>`:''}</a>`;}
function layout(body){const r=route(),names={overview:'Обзор качества',dialogues:'Диалоги',dialog:'Карточка диалога',checklists:'Чек-листы',appeals:'Апелляции',settings:'Настройки',accuracy:'Точность оценки'};return `<div class="shell"><aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">q</span><span><strong>CQA Studio<span style="color:#9add77">.</span></strong><small>CONVERSATION INTELLIGENCE</small></span></a><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav class="nav">${nav('overview','Обзор','overview')}${nav('dialogues','Диалоги','chat',data.records.length)}${nav('checklists','Чек-листы','check')}${nav('appeals','Апелляции','appeal',openAppeals().length||'')}${nav('accuracy','Точность','chart')}${nav('settings','Настройки','settings')}</nav><div class="sidebar-bottom"><div class="profile"><span class="avatar">QC</span><div><strong>Команда качества</strong><small>Демонстрационный доступ</small></div></div><div class="sidebar-footer">${icon('shield')} FREEDOM BROKER / CQA</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><span>Рабочее пространство</span><span>/</span><span>${names[r.view]||'Обзор'}</span></div><div class="top-actions"><span class="status"><i class="dot"></i> Данные сохранены</span><button class="icon-btn" data-action="reload" aria-label="Обновить данные">${icon('refresh')}</button><span class="today">${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',timeZone:'Asia/Almaty'})}</span></div></header><div class="content">${data.records.length&&data.records.every(r=>r.conversation_id.startsWith('demo-'))?'<div class="banner">Учебные примеры: все диалоги вымышлены. Для оценки рабочего набора загрузите свои данные через JSON или API.</div>':''}${body}<footer class="footer"><span>CQA STUDIO · РЕШЕНИЯ НА ОСНОВЕ ДИАЛОГА</span><span>RU / KZ / EN · v1.0</span></footer></div></main></div>`;}
function selectors(){return `<select class="model-switch" id="active-checklist" aria-label="Чек-лист оценки">${data.checklists.map(c=>`<option value="${esc(c.id)}" ${c.id===activeChecklist?'selected':''}>${esc(c.name)} · v${c.version}</option>`).join('')}</select><select class="model-switch" id="engine" aria-label="Способ оценки"><option value="rules" ${engine==='rules'?'selected':''}>Локальные правила · демо</option><option value="model" ${engine==='model'?'selected':''}>Модель · основная оценка</option></select>`;}
function progress(){return batch?`<div class="progress-wrap"><div class="progress-head"><span>${batch.done} / ${batch.total} · ${batch.cancelled?'Останавливаем…':'Оцениваем диалоги'}${batch.errors.length?` · ошибок: ${batch.errors.length}`:''}</span><button class="inline-link" data-action="cancel-batch">Остановить</button></div><div class="progress-bar"><i style="width:${batch.done/batch.total*100}%"></i></div></div>`:'';}
function overview(){const unique=data.records.map(r=>latest(r.conversation_id)).filter(Boolean),scored=unique.filter(e=>e.finalScore.total!==null),avg=scored.length?scored.reduce((s,e)=>s+e.finalScore.total,0)/scored.length:null;const languages=['RU','KZ','EN'].map(l=>({id:l,n:data.records.filter(r=>r.language===l).length}));const bins=[scored.filter(e=>e.finalScore.total<60).length,scored.filter(e=>e.finalScore.total>=60&&e.finalScore.total<85).length,scored.filter(e=>e.finalScore.total>=85).length];const max=Math.max(...bins,1);return `<div class="page-heading"><div><div class="eyebrow">CONVERSATION QUALITY ANALYTICS</div><h1>Качество в каждом диалоге</h1><p class="subtitle">От первого сообщения до взвешенной оценки. Всё в одном месте.</p></div><div class="actions"><button class="btn" data-action="import">${icon('upload')} Загрузить диалоги</button><button class="btn primary" data-action="batch" ${busy?'disabled':''}>${icon('play')} Оценить всё</button></div></div><div class="actions" style="margin-bottom:18px">${selectors()}<a class="inline-link" href="#settings">Настроить модель ${icon('arrow')}</a></div>${progress()}<div class="stats">${stat('Всего диалогов',data.records.length,`${data.records.filter(r=>r.channel==='agent chat').length} чатов · ${data.records.filter(r=>r.channel==='voice call').length} звонков`,'chat')}${stat('Средняя оценка',avg===null?'—':avg.toFixed(1),unique.length?`По ${unique.length} последним оценкам · предварительно`:'Готова после первой оценки','chart',avg===null?'':'/ 100')}${stat('Ожидают решения',openAppeals().length,`${data.appeals.filter(a=>a.status==='resolved').length} апелляций рассмотрено`,'appeal')}${stat('Языки диалогов',languages.filter(l=>l.n).length,'Русский · Қазақша · English','globe')}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Картина качества</h2><p>Распределение последних оценок диалогов</p></div><span class="badge neutral">${unique.length} оценено</span></div><div class="chart-body"><div class="quality-bars">${bins.map((n,i)=>`<div class="bar-column" style="height:${n?Math.max(8,n/max*85):3}%">${n?`<span class="bar-value">${n}</span>`:''}</div>`).join('')}${!unique.length?'<div class="chart-empty">Запустите оценку, чтобы увидеть распределение</div>':''}</div><div class="bar-labels"><span>Ниже 60</span><span>60 — 84</span><span>85 — 100</span></div><div class="legend"><span><i></i>Баллы от 0 до 100</span><span>Результаты правил требуют проверки</span></div></div></section><section class="panel"><div class="panel-head"><div><h2>Без языковых границ</h2><p>Состав загруженного набора</p></div>${icon('globe')}</div><div class="language-body">${languages.map((l,i)=>`<div class="language-row"><span class="lang-tile">${l.id}</span><div><strong>${['Русский','Қазақша','English'][i]}</strong><small>${Math.round(l.n/data.records.length*100)}% диалогов</small></div><span class="lang-number">${l.n}</span></div>`).join('')}<div class="language-bar">${languages.map(l=>`<span style="flex:${l.n}"></span>`).join('')}</div></div></section></div>${tablePanel(true)}`;}
function stat(label,value,meta,name,suffix=''){return `<div class="stat"><span class="stat-label">${label}</span><span class="stat-icon">${icon(name)}</span><div class="stat-value">${value} ${suffix?`<small>${suffix}</small>`:''}</div><div class="stat-meta">${meta}</div></div>`;}
function filtered(){return data.records.filter(r=>(filters.channel==='all'||r.channel===filters.channel)&&(filters.language==='all'||r.language===filters.language)&&(!filters.search||`${r.conversation_id} ${r.transcript.map(m=>m.text).join(' ')}`.toLowerCase().includes(filters.search.toLowerCase()))&&(filters.status==='all'||(filters.status==='evaluated'?!!latest(r.conversation_id):!latest(r.conversation_id))));}
function tablePanel(compact=false){const rows=filtered(),per=compact?6:12,pages=Math.max(1,Math.ceil(rows.length/per));filters.page=Math.min(filters.page,pages);const shown=rows.slice((filters.page-1)*per,filters.page*per);return `<section class="panel"><div class="panel-head"><div><h2>${compact?'В фокусе — диалоги':'Все диалоги'}</h2><p>${compact?'Откройте разговор, чтобы увидеть детали и оценку.':'Оригинальные роли, метки времени и история оценки.'}</p></div>${compact?`<a class="inline-link" href="#dialogues">Все ${data.records.length} ${icon('arrow')}</a>`:`<span class="badge neutral">${rows.length} найдено</span>`}</div><div class="table-tools"><div class="chips">${[['all','Все диалоги'],['agent chat','Чаты'],['voice call','Звонки']].map(([v,t])=>`<button class="chip ${filters.channel===v?'active':''}" data-action="channel" data-value="${v}">${t}</button>`).join('')}</div><div class="actions"><select id="language-filter" class="filter-select" aria-label="Фильтр языка"><option value="all">Все языки</option>${['RU','KZ','EN'].map(l=>`<option ${filters.language===l?'selected':''}>${l}</option>`).join('')}</select><label class="search">${icon('search')}<input id="search" value="${esc(filters.search)}" placeholder="Поиск по диалогам…" aria-label="Поиск по диалогам"></label></div></div><div class="table-scroll"><table><thead><tr><th>Диалог</th><th>Канал</th><th>Язык</th><th>Оценка</th><th>Статус</th><th></th></tr></thead><tbody>${shown.map(r=>{const e=latest(r.conversation_id),s=e?.finalScore,open=data.appeals.some(a=>a.conversationId===r.conversation_id&&a.status==='open');return `<tr data-open="${esc(r.conversation_id)}"><td><a href="#dialog/${encodeURIComponent(r.conversation_id)}" class="dialog-id" style="text-decoration:none"><span class="row-avatar">${icon(r.channel==='voice call'?'phone':'chat')}</span><span>${esc(r.conversation_id)}<small>${r.transcript.length} реплик · ${esc(r.transcript.at(-1).timestamp)}</small></span></a></td><td><span class="channel">${icon(r.channel==='voice call'?'phone':'chat')}${r.channel==='voice call'?'Звонок':'Чат'}</span></td><td><span class="badge neutral">${r.language}</span></td><td>${s?.total!=null?`<span class="score-number ${s.total<60?'low':''}">${s.total}</span><span class="score-track"><i style="width:${s.total}%"></i></span>`:'<span class="muted">—</span>'}</td><td><span class="badge ${open?'warning':s?.criticalErrors.length?'bad':e?'good':'neutral'}">${open?'Апелляция':s?.criticalErrors.length?'Грубая ошибка':e?(e.engine==='rules'?'Оценено · правила':'Оценено'):'Не оценено'}</span></td><td><button class="icon-btn" data-action="open-dialog" data-id="${esc(r.conversation_id)}" aria-label="Открыть ${esc(r.conversation_id)}">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table>${!shown.length?'<div class="empty">Нет диалогов по выбранным фильтрам.</div>':''}</div><div class="table-foot"><span>Показано ${rows.length?(filters.page-1)*per+1:0}–${Math.min(filters.page*per,rows.length)} из ${rows.length}</span><div class="actions"><button class="btn small" data-action="page" data-delta="-1" ${filters.page===1?'disabled':''}>${icon('left')}</button><span>${filters.page} / ${pages}</span><button class="btn small" data-action="page" data-delta="1" ${filters.page===pages?'disabled':''}>${icon('arrow')}</button></div></div></section>`;}
function dialogues(){return `<div class="page-heading"><div><div class="eyebrow">ДИАЛОГИ И ДОКАЗАТЕЛЬСТВА</div><h1>Всё начинается с разговора</h1><p class="subtitle">${data.records.length} диалогов. Три языка. Одна прозрачная система оценки.</p></div><div class="actions"><button class="btn" data-action="import">${icon('upload')} Загрузить</button><button class="btn primary" data-action="batch" ${busy?'disabled':''}>${icon('play')} Оценить выборку</button></div></div><div class="actions" style="margin-bottom:18px">${selectors()}<select id="status-filter" class="filter-select" aria-label="Статус оценки">${[['all','Все статусы'],['evaluated','Оценённые'],['new','Неоценённые']].map(([v,t])=>`<option value="${v}" ${filters.status===v?'selected':''}>${t}</option>`).join('')}</select></div>${progress()}${tablePanel()}`;}
function conversation(){const id=route().id,record=data.records.find(r=>r.conversation_id===id);if(!record)return '<div class="empty">Диалог не найден.</div>';const history=data.evaluations.filter(e=>e.conversationId===id);let e=history.find(e=>e.id===evaluationId)||history.at(-1);const transcript=e?.record||record,s=e?.finalScore;return `<a href="#dialogues" class="inline-link back">${icon('left')} К диалогам</a><div class="page-heading detail-heading"><div><div class="eyebrow">КАРТОЧКА ДИАЛОГА</div><h1>${esc(id)}</h1><div class="detail-meta"><span class="badge neutral">${record.language}</span><span class="badge neutral">${icon(record.channel==='voice call'?'phone':'chat')}${record.channel==='voice call'?'Голосовой звонок':'Чат с оператором'}</span><span class="version">${transcript.transcript.length} реплик</span></div></div><div class="actions">${selectors()}<button class="btn primary" data-action="evaluate" data-id="${esc(id)}" ${busy?'disabled':''}>${icon('play')} ${busy?'Оценка…':e?'Оценить снова':'Оценить диалог'}</button></div></div>${e?.engine==='rules'?`<div class="banner">${icon('info')}<span>Предварительная оценка по фразам и локальным правилам. Проверьте смысл ответа; для произвольных критериев подключите модель в настройках.</span></div>`:''}${s?.pendingCount?`<div class="banner warning">${icon('appeal')}<span>${s.pendingCount} критерий(ев) требует ручной проверки. Итог рассчитан по оценённым критериям и остаётся предварительным.</span></div>`:''}${e&&JSON.stringify(e.record)!==JSON.stringify(record)?`<div class="banner warning">${icon('clock')}Открыта оценка сохранённой версии транскрипта. После обновления данных запустите новую оценку.</div>`:''}<div class="detail-grid"><section class="panel">${e?`${history.length>1?`<div class="evaluation-selector"><span>Версия оценки</span><select id="evaluation-select" aria-label="История оценок">${history.map((x,i)=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>#${i+1} · ${date(x.createdAt)} · ${x.engine==='rules'?'правила':'модель'} · чек-лист v${x.checklist.version}</option>`).join('')}</select></div>`:''}<div class="score-summary"><div class="score-ring" style="--score:${s.total??0}"><div class="score-inner"><strong>${s.total??'—'}</strong><span>из 100 баллов</span></div></div><div><h2>${s.criticalErrors.length?'Обнаружена грубая ошибка':s.pendingCount?'Предварительный результат':'Результат оценки'}</h2><p>${esc(e.checklist.name)} · v${e.checklist.version}<br>${date(e.createdAt)}</p><div class="summary-tags"><span class="badge neutral">${s.naCount} N/A</span><span class="badge ${s.criticalErrors.length?'bad':'good'}">${s.criticalErrors.length?'Критическая ошибка':'С доказательствами'}</span></div>${e.appeals.some(a=>a.status==='resolved')?`<span class="score-change">Исходно ${e.originalScore.total??'—'} → финально ${s.total??'—'}</span>`:''}</div></div><div class="section-scores">${s.sections.filter(x=>x.weight>0).map(x=>`<div class="section-score"><span>${esc(x.name)}</span><strong>${x.score??'—'} / 100</strong></div>`).join('')}</div><div class="panel-head" style="padding-bottom:4px"><h3>Критерии оценки</h3><span class="criteria-count">${e.checklist.criteria.length} критериев</span></div>${e.finalResults.map(r=>criterionCard(e,r)).join('')}${e.verification?.mode==='verified'?`<div class="banner" style="margin:15px 20px">${icon('shield')}<span>Независимая проверка: ${Math.round(e.verification.agreementRate*100)}% совпадений. Критериев на разборе: ${e.verification.disagreements.length}.</span></div>`:''}${e.usage?`<div class="criterion-sub" style="padding:18px 24px">Модель: ${esc(e.usage.model)} · ${e.usage.calls} вызов · ${e.usage.inputTokens+e.usage.outputTokens} токенов · ${e.usage.costUSD===null?'стоимость не задана':`≈ $${e.usage.costUSD.toFixed(5)}`}</div>`:''}`:`<div class="detail-empty">${icon('chart')}<h2>Диалог готов к оценке</h2><p>Выберите чек-лист и способ оценки.<br>Результат сохранится вместе с доказательствами и версией настроек.</p><button class="btn primary" data-action="evaluate" data-id="${esc(id)}">${icon('play')} Запустить оценку</button></div>`}</section><section class="panel transcript-panel"><div class="panel-head"><div><h2>Слова имеют значение</h2><p>Транскрипт · исходные метки времени</p></div><span class="badge neutral">${record.language}</span></div>${transcript.audio_url?`<div class="audio-wrap"><audio id="audio" controls preload="none" referrerpolicy="no-referrer" src="${esc(transcript.audio_url)}"></audio><a href="${esc(transcript.audio_url)}" target="_blank" rel="noopener noreferrer">Открыть оригинальную запись ↗</a><p class="criterion-sub">При недоступности встроенного плеера откройте оригинал.</p></div>`:''}<div class="transcript-scroll" id="transcript">${transcript.transcript.map((m,i)=>`<article class="message ${m.speaker}" id="message-${i}"><div class="message-header"><strong>${{operator:'Оператор',client:'Клиент',bot:'Бот · контекст',system:'Система · контекст'}[m.speaker]}</strong><button class="evidence-link" data-action="seek" data-index="${i}" title="Перейти к этой метке времени">${esc(m.timestamp)}</button></div><p>${esc(m.text)}</p></article>`).join('')}</div></section></div>`;}
function criterionCard(e,r){const c=e.checklist.criteria.find(c=>c.id===r.criterionId),row=e.finalScore.rows.find(x=>x.criterionId===r.criterionId);const pending=e.appeals.find(a=>a.criterionId===c.id&&a.status==='open');const bad=c.critical?(c.criticalWhen==='pass'?r.answer===true:r.answer===false):r.answer===false;const pointLabel=c.weight===0?'Отдельный флаг · без баллов':r.answer===null?'Вес перераспределён':r.answer==='pending'?'Не включён в итог':`${row.points} / ${c.weight} взв. баллов`;return `<article class="criterion"><div class="criterion-header"><div><h3 class="criterion-title">${esc(c.number?c.number+'. ':'')}${esc(c.title)}</h3><div class="criterion-sub">${esc(c.section)} · вес ${c.weight} · ${c.type==='numeric'?`шкала ${c.min}–${c.max}`:'Да / Нет'}${r.reviewed?'<span class="review-label">Изменено проверяющим</span>':''}</div></div><div><span class="badge ${r.answer===null?'neutral':r.answer==='pending'?'warning':bad?'bad':'good'}">${answerText(r.answer)}${c.type==='numeric'&&typeof r.answer==='number'?` / ${c.max}`:''}</span><div class="criterion-points">${pointLabel}</div></div></div><p>${esc(r.explanation)}</p>${r.evidence.length?`<blockquote>${e.record.transcript[r.evidence[0]].speaker==='system'?'<strong>Системное сообщение</strong><br>':''}${esc(e.record.transcript[r.evidence[0]].text)}</blockquote>`:''}${r.contextEvidence?.length?`<div class="actions spaced"><span class="criterion-sub">Контекст: </span>${r.contextEvidence.map(i=>`<button class="evidence-link" data-action="evidence" data-start="${i}" data-end="${i}">${icon('link')} ${esc(e.record.transcript[i].timestamp)} · ${{client:'клиент',bot:'бот',system:'система',operator:'оператор'}[e.record.transcript[i].speaker]}</button>`).join('')}</div>`:''}<div class="criterion-bottom"><div class="actions">${r.evidence.length?r.evidence.map(i=>`<button class="evidence-link" data-action="evidence" data-start="${i}" data-end="${i}">${icon('link')} ${esc(e.record.transcript[i].timestamp)}</button>`).join(''):r.checkedRange?`<button class="evidence-link" data-action="evidence" data-start="${r.checkedRange.start}" data-end="${r.checkedRange.end}">${icon('search')} Проверенный участок ${r.checkedRange.start+1}–${r.checkedRange.end+1}</button>`:''}</div><button class="inline-link" data-action="appeal" data-evaluation="${e.id}" data-criterion="${esc(c.id)}" ${pending?'disabled':''}>${pending?'Апелляция открыта':'Оспорить'}</button></div></article>`;}
function checklistPage(){if(!draft||!data.checklists.some(c=>c.id===draftId)&&draftId!=='new'){draft=structuredClone(currentCheck());draftId=draft.id;}return `<div class="page-heading"><div><div class="eyebrow">КОНФИГУРАЦИЯ ОЦЕНКИ</div><h1>Ваш стандарт качества</h1><p class="subtitle">Меняйте критерии через интерфейс. Новая версия применяется к следующим оценкам.</p></div><div class="actions"><button class="btn" data-action="import-checklist">${icon('upload')} Импорт JSON</button><button class="btn primary" data-action="new-checklist">${icon('plus')} Новый чек-лист</button></div></div><div class="banner ${draft.provenance==='official'?'':'warning'}">${icon('info')}<span>${draft.provenance==='official'?'Официальный чек-лист Freedom Broker: 8 критериев, вес 100, заданные ступени шкал, итог до двух знаков. Грубые ошибки отмечаются отдельно без баллов.':draft.provenance==='official-modified'?'Эта версия создана на основе официального чек-листа и содержит сохранённые изменения.':'Пользовательский или демонстрационный чек-лист. Для контрольного набора выберите официальный Freedom Broker либо его согласованную версию.'}</span></div><div class="checklist-layout"><aside class="panel">${data.checklists.map(c=>`<button class="checklist-item ${c.id===draft.id?'active':''}" data-action="select-checklist" data-id="${esc(c.id)}"><strong>${esc(c.name)}</strong><span>${c.criteria.length} критериев · версия ${c.version}</span><span>${c.provenance==='official'?'Официальный':c.provenance==='official-modified'?'Официальный · изменён':c.provenance.startsWith('demo')?'Демонстрационный':'Пользовательский'}</span></button>`).join('')}<button class="checklist-item inline-link" data-action="export-checklist">${icon('download')} Экспорт текущего</button></aside><form id="checklist-form" class="panel"><div class="editor"><div class="editor-label"><h2>Редактор чек-листа</h2><span class="version">v${draft.version||1}</span></div><div class="form-stack"><label><span>Название</span><input required maxlength="160" name="name" value="${esc(draft.name)}"></label><label><span>Общие правила чек-листа</span><textarea name="instructions" rows="6">${esc(draft.instructions||'')}</textarea><small>Эти инструкции передаются модели вместе с текущими критериями. Их тоже можно изменить для новой версии.</small></label><div class="form-grid"><label><span>Округление, знаков</span><select name="rounding">${[0,1,2].map(n=>`<option ${draft.rounding===n?'selected':''}>${n}</option>`).join('')}</select></label><label><span>Грубая ошибка</span><select name="criticalPolicy"><option value="flag" ${draft.criticalPolicy==='flag'?'selected':''}>Отдельная отметка</option><option value="zero" ${draft.criticalPolicy==='zero'?'selected':''}>Обнулить итог</option></select></label></div></div><div id="criteria-editors">${draft.criteria.map((c,i)=>criterionEditor(c,i)).join('')}</div><div class="editor-footer"><button type="button" class="btn" data-action="add-criterion">${icon('plus')} Добавить критерий</button><button class="btn primary" type="submit">${icon('save')} Сохранить версию</button></div></div></form></div>`;}
function criterionEditor(c,i){return `<section class="criterion-editor" data-criterion-editor="${i}"><input type="hidden" name="number" value="${esc(c.number||String(i+1).padStart(2,'0'))}"><input type="hidden" name="id" value="${esc(c.id)}"><div class="editor-label"><strong>Критерий ${String(i+1).padStart(2,'0')}</strong><button type="button" class="icon-btn" data-action="delete-criterion" data-index="${i}" aria-label="Удалить критерий ${i+1}">${icon('trash')}</button></div><label><span>Формулировка</span><input required name="title" maxlength="180" value="${esc(c.title)}"></label><label><span>Инструкция для оценки</span><textarea name="description" required>${esc(c.description)}</textarea></label><div class="form-grid three"><label><span>Секция</span><input name="section" value="${esc(c.section)}"></label><label><span>Вес</span><input type="number" name="weight" min="0" max="1000" step="any" required value="${c.weight}"></label><label><span>Тип ответа</span><select name="type" data-scale="${i}"><option value="boolean" ${c.type==='boolean'?'selected':''}>Да / Нет</option><option value="numeric" ${c.type==='numeric'?'selected':''}>Числовая шкала</option></select></label></div><div class="form-grid"><label><span>Источник доказательств</span><select name="modality"><option value="text" ${c.modality!=='audio'?'selected':''}>Транскрипт</option><option value="audio" ${c.modality==='audio'?'selected':''}>Требуется прослушивание</option></select></label><label><span>Область проверки</span><select name="scope">${[['whole','Весь диалог'],['first_operator','Только первый ответ оператора'],['opening','Начало работы оператора'],['closing','Завершение диалога']].map(([v,t])=>`<option value="${v}" ${(c.scope||'whole')===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="form-grid scale-fields ${c.type==='numeric'?'':'hidden'}"><label><span>Минимум</span><input type="number" step="any" name="min" value="${c.min}"></label><label><span>Максимум</span><input type="number" step="any" name="max" value="${c.max}"></label><label style="grid-column:1/-1"><span>Ступени шкалы: балл | описание, по одной на строку</span><textarea name="levels" rows="5">${esc((c.levels||[]).map(l=>`${l.value} | ${l.label}`).join('\n'))}</textarea><small>При заданных ступенях принимаются только эти значения. Для непрерывной шкалы оставьте пустым.</small></label></div><div class="form-grid"><label class="check-row"><input type="checkbox" name="allowNA" ${c.allowNA?'checked':''}><span>Разрешить N/A</span></label><label class="check-row"><input type="checkbox" name="critical" ${c.critical?'checked':''}><span>Грубая ошибка</span></label></div><div class="form-grid"><label><span>Когда применять N/A</span><input name="naRule" value="${esc(c.naRule)}"></label><label><span>Ошибка срабатывает при</span><select name="criticalWhen"><option value="pass" ${c.criticalWhen==='pass'?'selected':''}>Да / максимум шкалы</option><option value="fail" ${c.criticalWhen==='fail'?'selected':''}>Нет / минимум шкалы</option></select></label></div><details class="spaced"><summary class="muted" style="font-size:10px;cursor:pointer">Локальное правило без модели</summary><label><span>Способ проверки</span><select name="ruleKind"><option value="manual" ${c.rule.kind==='manual'?'selected':''}>Ручная проверка / модель</option><option value="keywords" ${c.rule.kind==='keywords'?'selected':''}>Наличие фраз</option><option value="absence" ${c.rule.kind==='absence'?'selected':''}>Отсутствие фраз</option></select></label><label><span>Фразы оператора, через ;</span><textarea name="terms">${esc(c.rule.terms.join('; '))}</textarea></label><label><span>Условия применимости: фразы контекста, через ;</span><input name="applicableTerms" value="${esc(c.rule.applicableTerms.join('; '))}"><small>Если ни одной фразы нет и N/A разрешён, критерий неприменим.</small></label></details></section>`;}
function captureDraft(){const form=$('#checklist-form');if(!form)return;const field=(el,n)=>el.querySelector(`[name="${n}"]`);draft.name=field(form,'name').value;draft.instructions=field(form,'instructions').value;draft.rounding=Number(field(form,'rounding').value);draft.criticalPolicy=field(form,'criticalPolicy').value;draft.criteria=[...form.querySelectorAll('[data-criterion-editor]')].map(el=>{const val=n=>field(el,n).value;return {id:val('id'),number:val('number'),title:val('title'),description:val('description'),section:val('section'),weight:Number(val('weight')),type:val('type'),modality:val('modality'),scope:val('scope'),levels:val('levels').split(/\r?\n/).filter(l=>l.trim()).map(line=>{const [score,...label]=line.split('|');return {value:Number(score.trim()),label:label.join('|').trim()};}),min:Number(val('min')),max:Number(val('max')),allowNA:field(el,'allowNA').checked,naRule:val('naRule'),critical:field(el,'critical').checked,criticalWhen:val('criticalWhen'),rule:{kind:val('ruleKind'),terms:val('terms').split(';').map(s=>s.trim()).filter(Boolean),applicableTerms:val('applicableTerms').split(';').map(s=>s.trim()).filter(Boolean)}};});}
function appealsPage(){const open=openAppeals(),closed=data.appeals.filter(a=>a.status==='resolved');return `<div class="page-heading"><div><div class="eyebrow">ПРАВО НА ПЕРЕСМОТР</div><h1>Справедливость в деталях</h1><p class="subtitle">Комментарий оператора, доказательства и решение проверяющего — рядом.</p></div><span class="badge warning">${open.length} ожидают решения</span></div><div class="banner">${icon('shield')}Подача апелляции и решение проверяющего — отдельные действия. Для демонстрации вход не требуется.</div>${!data.appeals.length?`<div class="panel empty">${icon('check')}<h2>Всё спокойно</h2><p class="spaced">Чтобы подать апелляцию, откройте оценённый диалог<br>и нажмите «Оспорить» у нужного критерия.</p><a class="btn spaced" href="#dialogues">Открыть диалоги ${icon('arrow')}</a></div>`:`${open.length?'<div class="eyebrow">ОЖИДАЮТ РЕШЕНИЯ</div>':''}${open.map(appealCard).join('')}${closed.length?'<div class="eyebrow spaced">РАССМОТРЕНЫ</div>':''}${closed.toReversed().map(appealCard).join('')}`}`;}
function appealCard(a){const e=data.evaluations.find(e=>e.id===a.evaluationId),c=e.checklist.criteria.find(c=>c.id===a.criterionId),result=e.results.find(r=>r.criterionId===a.criterionId);return `<article class="panel appeal-card"><div class="criterion-header"><div><a href="#dialog/${encodeURIComponent(a.conversationId)}" class="inline-link" data-evaluation-link="${e.id}">${esc(a.conversationId)} ${icon('link')}</a><h3 class="spaced" style="margin-top:9px">${esc(c.title)}</h3><div class="criterion-sub">${date(a.createdAt)} · Оспаривается: ${answerText(a.disputedAnswer??a.originalAnswer)} · Исходно: ${answerText(a.originalAnswer)}</div></div><span class="badge ${a.status==='open'?'warning':'good'}">${a.status==='open'?'На рассмотрении':a.decision==='change'?'Оценка изменена':'Оценка подтверждена'}</span></div><div class="appeal-body"><strong>Комментарий к апелляции</strong>${esc(a.comment)}</div><p class="card-description">Исходное обоснование: ${esc(result.explanation)}</p>${result.evidence.length?`<div class="appeal-body"><strong>Доказательство · ${esc(e.record.transcript[result.evidence[0]].timestamp)}</strong>${esc(e.record.transcript[result.evidence[0]].text)}</div>`:`<p class="criterion-sub spaced">Проверенный участок: ${result.checkedRange?`${result.checkedRange.start+1}–${result.checkedRange.end+1}`:'весь диалог'}.</p>`}${a.status==='open'?`<div class="actions spaced"><a class="btn small" href="#dialog/${encodeURIComponent(a.conversationId)}" data-evaluation-link="${e.id}">Транскрипт ${icon('arrow')}</a><button class="btn primary small" data-action="review" data-id="${a.id}">${icon('check')} Принять решение</button></div>`:`<div class="review-decision"><strong>Решение проверяющего · ${date(a.resolvedAt)}</strong><br>${esc(a.reason)}<br>Финальный ответ: ${answerText(a.newAnswer)} · Итог диалога: ${e.finalScore.total??'—'} / 100</div>`}</article>`;}
function settingsPage(){return `<div class="page-heading"><div><div class="eyebrow">ИНСТРУМЕНТЫ КОМАНДЫ</div><h1>Настройте под свою задачу</h1><p class="subtitle">Выберите модель, подключите данные и подготовьте экспорт.</p></div><button class="btn" data-action="export">${icon('download')} Экспорт проекта</button></div><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Сервис оценки</h2><p>OpenAI-совместимый Chat Completions API</p></div>${icon('spark')}</div><form id="settings-form" class="editor form-stack" style="padding-top:0"><div class="banner slim">${icon('info')}Без ключа доступны локальные правила. Произвольные смысловые критерии оцениваются подключённой моделью.</div><label><span>Базовый URL</span><input required type="url" name="baseURL" value="${esc(data.settings.baseURL)}"></label><label><span>Название модели</span><input name="model" value="${esc(data.settings.model)}" placeholder="Идентификатор модели у вашего провайдера"></label><label><span>API-ключ для текущей вкладки</span><input type="password" name="apiKey" autocomplete="off" value="${esc(modelKey)}" placeholder="${data.modelConfigured?'Ключ настроен на сервере':'Введите ключ провайдера'}"><small>Ключ хранится только в памяти вкладки. Для постоянной настройки используйте переменные окружения сервера.</small></label><label><span>Уровень рассуждения Gemini</span><select name="reasoningEffort">${[['low','Low · быстрее'],['medium','Medium · больше времени'],['high','High · максимальное рассуждение']].map(([v,t])=>`<option value="${v}" ${(data.settings.reasoningEffort||'low')===v?'selected':''}>${t}</option>`).join('')}</select><small>Применяется к Gemini. Сравните точность режимов на эталоне; больший уровень может отвечать дольше.</small></label><label><span>Проверка точности</span><select name="verificationMode"><option value="verified" ${data.settings.verificationMode!=='single'?'selected':''}>Два независимых прохода + разбор расхождений</option><option value="single" ${data.settings.verificationMode==='single'?'selected':''}>Один проход</option></select><small>Повторная проверка требует 2–3 вызовов. Её влияние на точность проверяется по Ground Truth.</small></label><div class="form-grid"><label><span>Вход, USD / 1 млн токенов</span><input type="number" min="0" max="1000" step="any" name="inputPrice" value="${data.settings.inputPrice}"></label><label><span>Выход, USD / 1 млн токенов</span><input type="number" min="0" max="1000" step="any" name="outputPrice" value="${data.settings.outputPrice}"></label></div><p class="criterion-sub">Укажите актуальные цены своего тарифа. Нули означают, что стоимость не рассчитана.</p><div class="actions"><button class="btn primary">${icon('save')} Сохранить настройки</button><button type="button" class="btn ghost" data-action="clear-key">Убрать ключ</button></div></form></section><aside><section class="panel settings-copy"><h3>Как получается итог</h3><p>Числовая шкала приводится к диапазону 0–1. Затем оценка умножается на вес критерия.</p><div class="formula">Итог = 100 × Σ(оценка × вес)<br> / Σ(применимые веса)</div><p>N/A исключается из знаменателя. Неоценённые критерии отмечаются отдельно, а итог помечается предварительным. Правило грубой ошибки и округление задаются в чек-листе.</p><h3>Данные организаторов</h3><p>Рабочий DEV-набор загрузите через JSON или API. В публичной версии четыре вымышленных учебных примера. Новый group_id задаётся при импорте из API.</p><button class="btn small spaced" data-action="import">${icon('upload')} Загрузить контрольный набор</button><h3>Для Dynamics 365</h3><p>Интерфейс работает на обычном HTML, CSS и JavaScript. Отдельный API, адаптивная сетка и режим <span class="inline-code">?embed=1</span> позволяют встроить его как HTML web resource.</p><h3>Экспорт с историей</h3><p>JSON включает диалоги, версии чек-листов, исходные оценки, решения по апелляциям и журнал действий. API-ключи в него не попадают.</p></section></aside></div>`;}
function render(){if(!data)return;const r=route();const pages={overview,dialogues,dialog:conversation,checklists:checklistPage,appeals:appealsPage,settings:settingsPage,accuracy:accuracyPage};$('#app').innerHTML=layout((pages[r.view]||overview)());
    if(new URLSearchParams(location.search).get('embed')==='1'){
        const menuBtn = document.querySelector('.mobile-menu');
        if(menuBtn) menuBtn.style.display = 'inline-flex';

        // Корректируем сетку под компактный режим
        document.querySelector('.shell').style.gridTemplateColumns = '1fr';
        document.querySelector('.main').xstyle.gridColumn = '1';}
}
function showModal(title,body,footer=''){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}<div id="modal-error" class="error-detail" role="alert"></div></div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!m.open)m.showModal();}
function openImport(tab='json'){const tabs=`<div class="tab-row">${[['json','JSON-файл'],['api','API'],['text','Транскрипт']].map(([v,l])=>`<button class="tab ${tab===v?'active':''}" data-action="import-tab" data-tab="${v}">${l}</button>`).join('')}</div>`;const common=`<label class="check-row spaced"><input type="checkbox" name="replaceExisting"><span>Разрешить обновление существующих диалогов</span></label>`;let body=tab==='json'?`<div class="upload-zone">${icon('upload')}<h3>Добавьте диалоги в JSON</h3><p>Массив, records или полный ответ API организаторов.</p><input type="file" name="file" accept=".json,application/json" required aria-label="Выбрать JSON"></div>${common}`:tab==='api'?`<div class="form-stack"><label><span>URL GET-запроса организаторов</span><input type="url" name="url" placeholder="https://…?group_id=DEV" ${data.organizerConfigured?'':'required'}><small>${data.organizerConfigured?'Можно оставить пустым: адрес настроен на сервере.':'Используйте адрес кнопки GET из PDF.'} Запрос выполняется сервером.</small></label><label><span>group_id</span><input name="groupId" value="DEV" required maxlength="100"></label>${common}</div>`:`<div class="form-stack"><div class="form-grid"><label><span>ID диалога</span><input name="conversationId" required value="custom-${Date.now().toString(36)}"></label><label><span>Язык</span><select name="language"><option>RU</option><option>KZ</option><option>EN</option></select></label></div><div class="form-grid"><label><span>Канал</span><select name="channel"><option value="agent chat">Чат</option><option value="voice call">Звонок</option></select></label><label><span>URL аудио (для звонка)</span><input type="url" name="audioUrl" placeholder="https://…"></label></div><label><span>Транскрипт или файл .txt</span><textarea name="transcript" rows="7" placeholder="00:00 client: Здравствуйте&#10;00:02 operator: Добрый день! Чем могу помочь?"></textarea><small>Формат: время роль: текст. Роли: client, operator, bot, system. Для звонков можно использовать ISO 8601.</small></label><input type="file" name="textFile" accept=".txt,text/plain" aria-label="Загрузить текстовый транскрипт">${common}</div>`;showModal('Загрузить диалоги',tabs+`<form id="import-form" data-tab="${tab}">${body}</form>`,`<button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" type="submit" form="import-form">${icon('upload')} Загрузить</button>`);}
function openAppeal(eid,cid){const e=data.evaluations.find(e=>e.id===eid),c=e.checklist.criteria.find(c=>c.id===cid),r=e.finalResults.find(r=>r.criterionId===cid);showModal('Оспорить оценку',`<form id="appeal-form" data-evaluation="${eid}" data-criterion="${esc(cid)}"><div class="banner slim">${icon('appeal')}<span>${esc(c.title)} · текущий ответ: ${answerText(r.answer)}</span></div><label><span>Что нужно пересмотреть?</span><textarea name="comment" required maxlength="4000" rows="5" placeholder="Укажите, с чем вы не согласны, и приведите аргумент из диалога."></textarea></label></form>`,`<button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" type="submit" form="appeal-form">Подать апелляцию ${icon('arrow')}</button>`);}
function answerOptions(c,current){
  if(c.type==='numeric'){
    const control=c.levels?.length?`<select name="numericAnswer">${c.levels.map(l=>`<option value="${l.value}" ${current===l.value?'selected':''}>${l.value} — ${esc(l.label)}</option>`).join('')}</select>`:`<input type="number" name="numericAnswer" step="any" min="${c.min}" max="${c.max}" value="${typeof current==='number'?current:c.min}">`;
    return control+`<small>${c.levels?.length?'Выберите ступень шкалы.':`Шкала ${c.min}–${c.max}.`}</small><select name="answerMode"><option value="number">Числовая оценка</option>${c.allowNA?`<option value="na" ${current===null?'selected':''}>N/A</option>`:''}<option value="pending" ${current==='pending'?'selected':''}>Требует проверки</option></select>`;
  }
  return `<select name="booleanAnswer"><option value="true" ${current===true?'selected':''}>Да</option><option value="false" ${current===false?'selected':''}>Нет</option>${c.allowNA?`<option value="na" ${current===null?'selected':''}>N/A</option>`:''}<option value="pending" ${current==='pending'?'selected':''}>Требует проверки</option></select>`;
}
function openReview(id){const a=data.appeals.find(a=>a.id===id),e=data.evaluations.find(e=>e.id===a.evaluationId),c=e.checklist.criteria.find(c=>c.id===a.criterionId),r=e.finalResults.find(r=>r.criterionId===c.id);showModal('Решение проверяющего',`<form id="resolve-form" data-id="${id}"><div class="appeal-body"><strong>${esc(c.title)} · оспаривается ${answerText(a.disputedAnswer)}</strong>${esc(a.comment)}</div><p class="card-description">Обоснование: ${esc(r.explanation)}</p>${r.evidence.length?`<div class="appeal-body"><strong>${e.record.transcript[r.evidence[0]].speaker==='system'?'Системное сообщение':'Реплика оператора'}</strong>${esc(e.record.transcript[r.evidence[0]].text)}</div>`:`<div class="appeal-body">Проверенный участок: ${r.checkedRange?`${r.checkedRange.start+1}–${r.checkedRange.end+1}`:'весь диалог'}. Откройте карточку для просмотра транскрипта.</div>`}<div class="form-stack spaced"><label><span>Решение</span><select name="decision" id="review-decision"><option value="confirm">Подтвердить текущую оценку</option><option value="change">Изменить оценку</option></select></label><label id="new-answer-wrap" class="hidden"><span>Новый ответ</span>${answerOptions(c,r.answer)}</label><label><span>Причина решения</span><textarea name="reason" required maxlength="4000" rows="3" placeholder="Объясните решение со ссылкой на содержание диалога."></textarea></label></div></form>`,`<button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" type="submit" form="resolve-form">${icon('check')} Сохранить решение</button>`);}
function evidence(start,end){document.querySelectorAll('.message.highlight').forEach(el=>el.classList.remove('highlight'));for(let i=start;i<=end;i++)$(`#message-${i}`)?.classList.add('highlight');$(`#message-${start}`)?.scrollIntoView({behavior:'smooth',block:'nearest'});seekAudio(start);}
function seekAudio(index){const audio=$('#audio');if(!audio)return;const r=route(),e=data.evaluations.find(e=>e.id===evaluationId)||latest(r.id),record=e?.record||data.records.find(r=>r.conversation_id===route().id),ts=record.transcript[index]?.timestamp;let seconds=0;if(/^\d+:\d{2}(?::\d{2}(?:\.\d+)?)?$/.test(ts)){const p=ts.split(':').map(Number);seconds=p.length===2?p[0]*60+p[1]:p[0]*3600+p[1]*60+p[2];}else seconds=Math.max(0,(Date.parse(ts)-Date.parse(record.transcript[0].timestamp))/1000);if(Number.isFinite(seconds)){const seek=()=>{audio.currentTime=seconds;};if(audio.readyState>=1)seek();else{audio.addEventListener('loadedmetadata',seek,{once:true});audio.preload='metadata';audio.load();}toast(`Аудио: ${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')} · нажмите воспроизведение`);}}
async function evaluateOne(id){if(busy)return;if(engine==='model'&&!(modelKey||data.modelConfigured)){location.hash='settings';toast('Подключите модель и API-ключ для основной оценки.');return;}busy=true;render();try{const e=await api('evaluate',{conversationId:id,checklistId:activeChecklist,engine});evaluationId=e.id;await reload();toast('Оценка сохранена. Доказательства готовы.');}finally{busy=false;render();}}
async function evaluateBatch(){if(busy)return;if(engine==='model'&&!(modelKey||data.modelConfigured)){location.hash='settings';toast('Подключите модель и API-ключ для основной оценки.');return;}const ids=filtered().map(r=>r.conversation_id);if(!ids.length)return toast('Нет диалогов в выборке.');busy=true;batch={total:ids.length,done:0,errors:[],cancelled:false};render();for(const id of ids){if(batch.cancelled)break;try{await api('evaluate',{conversationId:id,checklistId:activeChecklist,engine});}catch(error){batch.errors.push(`${id}: ${error.message}`);if(engine==='model'&&(['MODEL_AUTH','MODEL_NOT_FOUND','MODEL_RATE_LIMIT','MODEL_CONNECTION','MODEL_REDIRECT','MODEL_PROVIDER','MODEL_TIMEOUT','REQUEST_TIMEOUT'].includes(error.code)||batch.errors.length>=3))batch.cancelled=true;}batch.done++;if(batch.done%3===0||batch.done===batch.total){await reload();render();}}const result=batch;batch=null;busy=false;await reload();render();toast(`Обработано ${result.done} из ${result.total}. Ошибок: ${result.errors.length}.`,!!result.errors.length);if(result.errors.length)showModal('Результаты пакетной оценки',`<p class="card-description">Успешные оценки сохранены. Ошибочные диалоги можно запустить повторно.</p><div class="error-detail">${esc(result.errors.join('\n'))}</div>`,`<button class="btn" data-action="close-modal">Закрыть</button>`);}
function downloadJSON(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{const link=event.target.closest('[data-evaluation-link]');if(link)evaluationId=link.dataset.evaluationLink;const button=event.target.closest('[data-action]');if(!button){const row=event.target.closest('tr[data-open]');if(row&&!event.target.closest('a')){evaluationId='';location.hash='dialog/'+encodeURIComponent(row.dataset.open);}return;}if(button.disabled)return;const a=button.dataset.action;try{
  if(a==='menu')$('.sidebar').classList.toggle('open');
  if(a==='reload'){await reload();render();toast('Данные обновлены.');}
  if(a==='import')openImport();if(a==='import-tab')openImport(button.dataset.tab);
  if(a==='close-modal')$('#modal').close();
  if(a==='channel'){filters.channel=button.dataset.value;filters.page=1;render();}
  if(a==='page'){filters.page+=Number(button.dataset.delta);render();}
  if(a==='open-dialog'){evaluationId='';location.hash='dialog/'+encodeURIComponent(button.dataset.id);}
  if(a==='evaluate')await evaluateOne(button.dataset.id);
  if(a==='batch')await evaluateBatch();if(a==='cancel-batch'&&batch)batch.cancelled=true;
  if(a==='evidence')evidence(Number(button.dataset.start),Number(button.dataset.end));
  if(a==='seek')seekAudio(Number(button.dataset.index));
  if(a==='appeal')openAppeal(button.dataset.evaluation,button.dataset.criterion);
  if(a==='review')openReview(button.dataset.id);
  if(a==='select-checklist'){captureDraft();draft=structuredClone(data.checklists.find(c=>c.id===button.dataset.id));draftId=draft.id;render();}
  if(a==='new-checklist'){draft={id:crypto.randomUUID(),name:'Новый чек-лист',version:1,rounding:1,criticalPolicy:'flag',provenance:'custom',criteria:[{id:crypto.randomUUID(),title:'Новый критерий',description:'Опишите, какое действие оператора нужно оценить.',section:'Общее',weight:10,type:'boolean',min:0,max:1,allowNA:false,naRule:'',critical:false,criticalWhen:'pass',rule:{kind:'manual',terms:[],applicableTerms:[]}}]};draftId='new';render();}
  if(a==='add-criterion'){captureDraft();if(draft.criteria.length>=40)throw new Error('Максимум 40 критериев.');draft.criteria.push({id:crypto.randomUUID(),title:'',description:'',section:'Общее',weight:10,type:'boolean',min:0,max:1,allowNA:false,naRule:'',critical:false,criticalWhen:'pass',rule:{kind:'manual',terms:[],applicableTerms:[]}});render();document.querySelector('.criterion-editor:last-child')?.scrollIntoView({behavior:'smooth',block:'center'});}
  if(a==='delete-criterion'){captureDraft();if(draft.criteria.length===1)throw new Error('Оставьте хотя бы один критерий.');draft.criteria.splice(Number(button.dataset.index),1);render();}
  if(a==='export-checklist'){captureDraft();downloadJSON(draft,'cqa-checklist.json');}
  if(a==='import-checklist'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const p=JSON.parse(await input.files[0].text());draft={...p,id:crypto.randomUUID(),version:1,provenance:'custom'};const saved=await api('checklists',draft);await reload();draft=structuredClone(saved);draftId=saved.id;activeChecklist=saved.id;render();toast('Чек-лист импортирован.');}catch(e){toast(e.message,true);}};input.click();}
  if(a==='export')downloadJSON(await api('export'),'cqa-workspace.json');
  if(a==='truth-template')truthTemplate();if(a==='benchmark')openBenchmark();if(a==='export-benchmark'){const r=(data.benchmarks||[]).find(r=>r.id===button.dataset.id);downloadJSON(r,'cqa-accuracy-report.json');}if(a==='clear-key'){modelKey='';render();toast('Ключ удалён из памяти вкладки.');}
}catch(error){toast(error.message,true);}});
let searchTimer;
document.addEventListener('input',event=>{if(event.target.id==='search'){const position=event.target.selectionStart;filters.search=event.target.value;filters.page=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const input=$('#search');input?.focus();input?.setSelectionRange(position,position);},200);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='active-checklist')activeChecklist=el.value;if(el.id==='engine')engine=el.value;if(el.id==='language-filter'){filters.language=el.value;filters.page=1;render();}if(el.id==='status-filter'){filters.status=el.value;filters.page=1;render();}if(el.id==='evaluation-select'){evaluationId=el.value;render();}if(el.id==='review-decision')$('#new-answer-wrap').classList.toggle('hidden',el.value!=='change');if(el.dataset.scale!==undefined){const group=el.closest('.criterion-editor');group.querySelector('.scale-fields').classList.toggle('hidden',el.value!=='numeric');if(el.value==='numeric'&&group.querySelector('[name=max]').value==='1')group.querySelector('[name=max]').value='5';}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['import-form','checklist-form','appeal-form','resolve-form','settings-form','benchmark-form'].includes(form.id))return;event.preventDefault();const submit=document.querySelector(`[form="${form.id}"][type="submit"]`)||form.querySelector('[type=submit]')||form.querySelector('button:not([type=button])');if(submit)submit.disabled=true;const val=n=>form.elements.namedItem(n)?.value;try{
  if(form.id==='import-form'){
    let payload;const replaceExisting=form.elements.replaceExisting.checked;
    if(form.dataset.tab==='json'){const file=form.elements.file.files[0];if(!file)throw new Error('Выберите JSON-файл.');if(file.size>6*1024*1024)throw new Error('Максимальный размер файла — 6 МБ.');payload={payload:JSON.parse(await file.text()),replaceExisting};}
    else if(form.dataset.tab==='api')payload={url:val('url'),useOrganizer:!val('url'),groupId:val('groupId'),replaceExisting};
    else{let text=val('transcript');const file=form.elements.textFile.files[0];if(file){if(file.size>6*1024*1024)throw new Error('Файл больше 6 МБ.');text=await file.text();}const transcript=text.split(/\r?\n/).filter(s=>s.trim()).map((line,i)=>{const m=line.match(/^\[?([^\s\]]+)\]?\s+(client|operator|bot|system)\s*:\s*(.+)$/i);if(!m)throw new Error(`Строка ${i+1}: нужен формат «00:00 operator: Текст».`);return {timestamp:m[1],speaker:m[2].toLowerCase(),text:m[3]};});payload={payload:[{conversation_id:val('conversationId'),language:val('language'),channel:val('channel'),audio_url:val('audioUrl')||null,transcript}],replaceExisting};}
    const r=await api('import',payload);await reload();$('#modal').close();render();toast(`Добавлено ${r.added}, обновлено ${r.updated}, без изменений ${r.unchanged}.`);
  }
  if(form.id==='checklist-form'){captureDraft();const saved=await api('checklists',draft);activeChecklist=saved.id;draft=structuredClone(saved);draftId=saved.id;await reload();render();toast(`Чек-лист сохранён · версия ${saved.version}.`);}
  if(form.id==='appeal-form'){await api('appeals',{evaluationId:form.dataset.evaluation,criterionId:form.dataset.criterion,comment:val('comment')});await reload();$('#modal').close();render();toast('Апелляция сохранена и доступна проверяющему.');}
  if(form.id==='resolve-form'){const a=data.appeals.find(a=>a.id===form.dataset.id),e=data.evaluations.find(e=>e.id===a.evaluationId),c=e.checklist.criteria.find(c=>c.id===a.criterionId);let newAnswer;const raw=c.type==='numeric'?val('answerMode'):val('booleanAnswer');newAnswer=raw==='na'?null:raw==='pending'?'pending':c.type==='numeric'?Number(val('numericAnswer')):raw==='true';await api('appeals/resolve',{appealId:a.id,decision:val('decision'),newAnswer,reason:val('reason')});await reload();$('#modal').close();render();toast('Решение сохранено. Итог пересчитан.');}
  if(form.id==='benchmark-form'){const file=form.elements.file.files[0];if(!file)throw new Error('Выберите Ground Truth JSON.');if(file.size>6*1024*1024)throw new Error('Файл больше 6 МБ.');const payload=JSON.parse(await file.text());payload.engine=val('benchmarkEngine');await api('benchmark',payload);await reload();$('#modal').close();location.hash='accuracy';render();toast('Сравнение завершено. Показаны реальные расхождения.');}
  if(form.id==='settings-form'){modelKey=val('apiKey').trim();await api('settings',{baseURL:val('baseURL'),model:val('model'),inputPrice:Number(val('inputPrice')),outputPrice:Number(val('outputPrice')),verificationMode:val('verificationMode'),reasoningEffort:val('reasoningEffort')});await reload();render();toast('Настройки сохранены.');}
}catch(error){toast(error.message,true);if($('#modal').open&&$('#modal-error'))$('#modal-error').textContent=error.message;}finally{if(submit)submit.disabled=false;}});
window.addEventListener('hashchange',()=>{if(route().view!=='checklists')captureDraft();render();window.scrollTo({top:0});});
async function boot(){try{await reload();render();}catch(error){$('#app').innerHTML=`<div class="loading-screen"><span class="brand-mark">q</span><h2>Не удалось открыть данные</h2><p>${esc(error.message)}</p><button class="btn" data-action="reload">Повторить ${icon('refresh')}</button></div>`;}}
function accuracyPage(){const reports=data.benchmarks||[],report=reports.at(-1);return `<div class="page-heading"><div><div class="eyebrow">ПРОВЕРКА НА ЭТАЛОНЕ</div><h1>Точность можно измерить</h1><p class="subtitle">Сравнивайте исходную оценку модели с Ground Truth. Апелляции на метрики не влияют.</p></div><div class="actions"><button class="btn" data-action="truth-template">${icon('download')} Шаблон эталона</button><button class="btn primary" data-action="benchmark">${icon('chart')} Сравнить с эталоном</button></div></div>${report?`<div class="stats">${stat('Точные совпадения',(report.exactAccuracy*100).toFixed(1)+'%',`${report.exact} из ${report.compared} ответов`,'check')}${stat('Ошибка по шкале',(report.normalizedMAE*100).toFixed(1)+'%','Средняя нормированная абсолютная ошибка','chart')}${stat('Ошибка итогового балла',report.totalMAE===null?'—':report.totalMAE.toFixed(2),`${report.totalCompared} диалогов с полным эталоном`,'overview')}${stat('Сопоставлено диалогов',`${report.matched} / ${report.requested}`,`${report.pending} ответов требуют проверки`,'chat')}</div><div class="banner">${icon('info')}<span>Чек-лист ${esc(report.checklistId)} · v${report.checklistVersion} · ${report.engine==='model'?'модель':'демонстрационные правила'} · ${date(report.createdAt)}. Это измерение на загруженном эталоне; точность на неизвестных диалогах заранее неизвестна.</span></div><section class="panel"><div class="panel-head"><h2>Где возникают расхождения</h2><button class="btn small" data-action="export-benchmark" data-id="${report.id}">${icon('download')} Отчёт JSON</button></div><div class="table-scroll"><table><thead><tr><th>Критерий</th><th>Сравнений</th><th>Совпадения</th><th>Норм. ошибка</th></tr></thead><tbody>${report.byCriterion.map(c=>`<tr><td>${esc(c.title)}</td><td>${c.compared}</td><td><span class="badge ${c.accuracy>=.85?'good':'warning'}">${(c.accuracy*100).toFixed(1)}%</span></td><td>${(c.mae*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div></section><section class="panel spaced"><div class="panel-head"><h2>Сравнение по диалогам</h2><span class="badge neutral">Исходные оценки</span></div>${report.items.map(item=>`<div class="criterion"><div class="criterion-header"><a class="inline-link" href="#dialog/${encodeURIComponent(item.conversationId)}" data-evaluation-link="${esc(item.evaluationId||'')}">${esc(item.conversationId)} ${icon('link')}</a><span class="badge ${item.status!=='compared'?'warning':item.differences.length?'warning':'good'}">${item.status==='stale_evaluation'?'Нужна новая оценка':item.status!=='compared'?'Нет подходящей оценки':`${item.differences.length} расхождений`}</span></div>${item.status==='compared'?`<p>Итог модели: ${item.actualTotal??'—'} · эталон: ${item.expectedTotal??'неполный набор ответов'}</p>${item.differences.map(d=>`<p>${esc(d.title)}: эталон <strong>${esc(answerText(d.expected))}</strong>, система <strong>${esc(answerText(d.actual))}</strong>.</p>`).join('')}`:''}</div>`).join('')}</section>`:`<section class="panel empty">${icon('chart')}<h2>Пока нет эталонных оценок</h2><p class="spaced">Загрузите Ground Truth после оценки диалогов моделью.<br>Система покажет реальные совпадения, ошибку итогового балла и спорные критерии.</p><button class="btn spaced" data-action="truth-template">${icon('download')} Скачать шаблон формата</button></section>`}<div class="settings-grid spaced"><section class="panel settings-copy"><h3>Как подготовить контрольные 10 диалогов</h3><ol><li>Импортируйте новый набор через JSON или API с новым group_id.</li><li>Выберите официальный чек-лист и нужную версию.</li><li>Запустите модельную оценку; режим проверки задаётся в настройках.</li><li>Экспортируйте результаты с доказательствами и историей.</li></ol><p>Эталон не отправляется модели и не используется как подсказка. Все ответы создаются по новому транскрипту во время запроса.</p></section><section class="panel settings-copy"><h3>Что означает независимая проверка</h3><p>Второй проход не видит ответ первого. Если ответы расходятся или уверенность низкая, третий проход проверяет спорные критерии по исходному диалогу.</p><p class="spaced">Это дополнительная проверка, а не гарантия улучшения. Сравните её с одним проходом на собственном Ground Truth.</p></section></div>`;}
function truthTemplate(){const c=currentCheck(),records=data.records.slice(0,2).map(r=>({conversationId:r.conversation_id,answers:Object.fromEntries(c.criteria.map(x=>[x.id,x.type==='boolean'?'<true или false; null только при N/A>':x.levels?.length?`<одно из: ${x.levels.map(l=>l.value).join(', ')}${x.allowNA?'; null только при N/A':''}>`:`<число от ${x.min} до ${x.max}; null только при N/A>`]))}));downloadJSON({exampleOnly:true,instructions:'Заполните ответы из официального эталона. Удалите поле exampleOnly перед сравнением. Не используйте ответы системы как Ground Truth.',checklistId:c.id,checklistVersion:c.version,engine:'model',records},'ground-truth-template.json');}
function openBenchmark(){showModal('Сравнить с Ground Truth',`<form id="benchmark-form"><div class="banner slim">${icon('info')}<span>Укажите checklistId, checklistVersion и records[{conversationId, answers:{criterionId: ответ}}]. Сравниваются исходные оценки с совпадающей версией чек-листа.</span></div><div class="form-stack"><label><span>Эталонные оценки JSON</span><input type="file" name="file" accept=".json,application/json" required></label><label><span>Сравнить результаты</span><select name="benchmarkEngine"><option value="model">Языковая модель</option><option value="rules">Локальные правила · демо</option></select></label></div></form>`,`<button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" type="submit" form="benchmark-form">${icon('chart')} Сравнить</button>`);}
boot();